import os
import json
import numpy as np
import sys

N = 26

# Utils to read CSVs
def read_active_pairs_csv(path):
    pairs = set()
    try:
        with open(path, 'r') as f:
            header = f.readline()
            for line in f:
                parts = line.strip().split(',')
                if len(parts) < 2:
                    continue
                i = int(parts[0]); j = int(parts[1])
                if i > j:
                    i, j = j, i
                pairs.add((i, j))
    except Exception:
        return None
    return pairs

def read_active_boundary_csv(path):
    bset = set()
    try:
        with open(path, 'r') as f:
            header = f.readline()
            for line in f:
                parts = line.strip().split(',')
                if len(parts) < 2:
                    continue
                i = int(parts[0]); kind = parts[1]
                bset.add((i, kind))
    except Exception:
        return None
    return bset

def jaccard(a, b):
    if a is None or b is None:
        return None, None, None
    inter = a & b
    uni = a | b
    if len(uni) == 0:
        return 1.0, 0, 0
    return len(inter) / len(uni), len(inter), len(uni)

def load_saved_best():
    try:
        c = np.loadtxt('storage/noesis/latest_centers.txt')
        r = np.loadtxt('storage/noesis/latest_radii.txt')
        c = np.array(c, dtype=float).reshape(N, 2)
        r = np.array(r, dtype=float).reshape(N,)
        return c, r
    except Exception:
        return None, None

def grid_plus_hole_seed(r0=0.1 - 1e-8, eps=1e-8):
    coords = [0.1, 0.3, 0.5, 0.7, 0.9]
    centers = [[x, y] for x in coords for y in coords]
    d = float(np.linalg.norm(np.array([0.2,0.2]) - np.array([0.1,0.1])))
    radii = [float(r0)] * 25 + [float(d - r0 - eps)]
    return np.array(centers, dtype=float), np.array(radii, dtype=float)

def construct_packing():
    centers, radii = load_saved_best()
    if centers is None:
        centers, radii = grid_plus_hole_seed()

    # Paths
    mine_pairs_path = 'storage/noesis/exports/active_pairs_tol1e8.csv'
    mine_bdry_path  = 'storage/noesis/exports/active_boundary_tol1e8.csv'
    peer_pairs_path = 'storage/noesis/peer_active_pairs_tol1e8.csv'
    peer_bdry_path  = 'storage/noesis/peer_active_boundary_tol1e8.csv'

    # Load sets
    mine_pairs = read_active_pairs_csv(mine_pairs_path)
    mine_bdry  = read_active_boundary_csv(mine_bdry_path)
    peer_pairs = read_active_pairs_csv(peer_pairs_path)
    peer_bdry  = read_active_boundary_csv(peer_bdry_path)

    comp = {}
    comp['pairs'] = {}
    comp['boundary'] = {}

    if mine_pairs is not None and peer_pairs is not None:
        jc, inter, uni = jaccard(mine_pairs, peer_pairs)
        comp['pairs'] = {
            'mine_count': len(mine_pairs),
            'peer_count': len(peer_pairs),
            'jaccard': jc,
            'intersection': inter,
            'union': uni
        }
    else:
        comp['pairs']['available'] = False

    if mine_bdry is not None and peer_bdry is not None:
        jc_b, inter_b, uni_b = jaccard(mine_bdry, peer_bdry)
        comp['boundary'] = {
            'mine_count': len(mine_bdry),
            'peer_count': len(peer_bdry),
            'jaccard': jc_b,
            'intersection': inter_b,
            'union': uni_b
        }
    else:
        comp['boundary']['available'] = False

    # Write outputs
    try:
        os.makedirs('storage/noesis/exports', exist_ok=True)
        with open('storage/noesis/exports/jaccard_peer_tol1e8.json', 'w') as f:
            json.dump(comp, f, indent=2)
        with open('storage/noesis/exports/jaccard_peer_tol1e8.txt', 'w') as f:
            if 'jaccard' in comp.get('pairs', {}):
                f.write(f"Pairs: mine={comp['pairs']['mine_count']}, peer={comp['pairs']['peer_count']}, "
                        f"J={comp['pairs']['jaccard']:.6f} (|∩|={comp['pairs']['intersection']}, |∪|={comp['pairs']['union']})\n")
            else:
                f.write("Pairs: unavailable\n")
            if 'jaccard' in comp.get('boundary', {}):
                f.write(f"Boundary: mine={comp['boundary']['mine_count']}, peer={comp['boundary']['peer_count']}, "
                        f"J={comp['boundary']['jaccard']:.6f} (|∩|={comp['boundary']['intersection']}, |∪|={comp['boundary']['union']})\n")
            else:
                f.write("Boundary: unavailable\n")
    except Exception:
        pass

    return centers.astype(float), radii.astype(float)
